// Selected official application controller; generated by prepare_partner_detail_window_ui.py.
namespace Zjcs.Official.PartnersUI
{
using Object = UnityEngine.Object;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.WorldUI;
using MultiLanguageText = Zjcs.Official.WorldUI.WorldMultiLanguageText;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

public class NpcDetailPanelDetailContent : UIBase
{
	private enum NpcImageState
	{
		Empty,
		Static,
		Live
	}

	[SerializeField]
	private NpcAdventureConditionContent mConditionContent;

	[SerializeField]
	private SkeletonGraphicAnimSequence mAnimSequence;

	[SerializeField]
	private MultiLanguageText mNpcNameText;

	[SerializeField]
	private MultiLanguageText mSpecialNpcNameText;

	[SerializeField]
	private WorldStateSwitcher<bool> mSpecialNpcNameStates;

	[SerializeField]
	private Transform mModelSlot;

	[SerializeField]
	private Image mBgImage;

	[SerializeField]
	private ImageLocator mNpcImage;

	[SerializeField]
	private NpcDetailLiveController mLiveController;

	[SerializeField]
	private Button mNpcTouchBtn;

	[SerializeField]
	private NpcTalkUI mNpcTalkUI;

	[SerializeField]
	private WorldStateSwitcher<NpcImageState> mNpcImageStates;

	[SerializeField]
	private NpcCustomSizeController mNpcCustomSizeController;

	private bool mIsPlayingAnim;

	private PartnerDetailPresentationInfo mNpcInfo;

	private PartnerDetailAnimationInfo mFriendshipLevelInfo;

	private IPartnerDetailNpcData mNpcData;

	private List<AppearanceAnimData> mAnimDataList = new List<AppearanceAnimData>();

	private IProfessionAssetOperation<Sprite> mNpcBgHandle;

	private IProfessionAssetOperation<Sprite> mNpcImgHandle;

	private IProfessionAssetOperation<GameObject> mNpcModelHandle;


    private IPartnerDetailPresentationServices services;
    public void Configure(IPartnerDetailPresentationServices value)
    { services = value ?? throw new System.ArgumentNullException(nameof(value)); }

	private void Awake()
	{


		mAnimSequence.OnAnimEnd = OnAnimEnd;
		((UnityEvent)mNpcTouchBtn.onClick).AddListener((UnityAction)OnClickNpcTouchBtn);
	}

	protected override void OnEnableAndInited()
	{
		base.OnEnableAndInited();
		Refresh();
	}

	protected override void OnDisableAndInited()
	{
		mIsPlayingAnim = false;
		services.DestroyChildren(mModelSlot);
		ReleaseHandles();
		base.OnDisableAndInited();
	}

	public void Init(IPartnerDetailNpcData npcDataWrap, PartnerDetailPresentationInfo npcInfo)
	{
		InitWrapper(() =>
		{
			mNpcData = npcDataWrap;
			mNpcInfo = npcInfo;
			mFriendshipLevelInfo = services.GetFriendshipAnimation(mNpcData.NpcClassId, mNpcData.FriendShipLevel);
		});
	}

	private void ReleaseHandles()
	{
		if (mNpcBgHandle != null)
		{
			mNpcBgHandle.Dispose();
			mNpcBgHandle = null;
		}
		if (mNpcImgHandle != null)
		{
			mNpcImgHandle.Dispose();
			mNpcImgHandle = null;
		}
		if (mNpcModelHandle != null)
		{
			mNpcModelHandle.Dispose();
			mNpcModelHandle = null;
		}
	}

	private void Refresh()
	{




		ReleaseHandles();
		mNpcTalkUI.SetStateSwitcher(value: false);
		if ((Object)(object)mSpecialNpcNameText != (Object)null && (Object)(object)mNpcNameText != (Object)null)
		{
			bool flag = mNpcInfo.IsSpecial;
			if (flag)
			{
				mSpecialNpcNameText.SetKey(mNpcInfo.NameKey);
			}
			else
			{
				mNpcNameText.SetKey(mNpcInfo.NameKey);
			}
			mSpecialNpcNameStates.SetState(flag);
		}
		mNpcBgHandle = services.LoadSprite(mNpcInfo.BigBgImage);
		mBgImage.sprite = mNpcBgHandle.Result;
		string path;
		switch (services.GetFullBodyImagePath(mNpcInfo.Id, out path))
		{
		case PartnerFullBodyImageType.Live:
			mNpcImageStates.SetState(NpcImageState.Live);
			mLiveController.ShowNpc(mNpcInfo.Id);
			break;
		case PartnerFullBodyImageType.Static:
			mNpcImageStates.SetState(NpcImageState.Static);
			mNpcImgHandle = services.LoadSprite(path);
			mNpcImage.SetSprite(mNpcImgHandle.Result);
			((Graphic)mNpcImage.Image).color = new Color(((Graphic)mNpcImage.Image).color.r, ((Graphic)mNpcImage.Image).color.g, ((Graphic)mNpcImage.Image).color.b, mNpcInfo.IsShadow ? 0.667f : 1f);
			break;
		default:
			mNpcImageStates.SetState(NpcImageState.Empty);
			break;
		}
		mConditionContent.Init(mNpcInfo);
		services.DestroyChildren(mModelSlot);
		mNpcModelHandle = services.LoadPrefab(mNpcInfo.FigureModelUI);
		Component skeletonGraphic = services.GetSkeletonGraphic(services.InstantiateKeepScale(mNpcModelHandle.Result, mModelSlot));
		mAnimSequence.SetSkeletonGraphic(skeletonGraphic);
		if ((Object)(object)mNpcCustomSizeController != (Object)null)
		{
			mNpcCustomSizeController.ApplyForNpc(mNpcInfo.Id);
		}
		if (((Component)skeletonGraphic).gameObject.activeInHierarchy)
		{
			string npcStartingAnimName = services.GetNpcStartingAnimName(mNpcData.NpcClassId);
			services.PlayAnimation(skeletonGraphic, npcStartingAnimName, loop: true);
		}
	}

	private void OnAnimEnd(string animName)
	{
		if (string.Equals(animName, mFriendshipLevelInfo.Animation))
		{
			mIsPlayingAnim = false;
		}
	}

	private void OnClickNpcTouchBtn()
	{
		if (!mIsPlayingAnim && !string.IsNullOrEmpty(mFriendshipLevelInfo.Animation))
		{
			mIsPlayingAnim = true;
			mAnimDataList.Clear();
			AppearanceAnimData item = new AppearanceAnimData
			{
				AnimName = mFriendshipLevelInfo.Animation,
				LoopTimes = 1
			};
			mAnimDataList.Add(item);
			AppearanceAnimData item2 = new AppearanceAnimData
			{
				AnimName = services.GetNpcStartingAnimName(mNpcData.NpcClassId),
				LoopTimes = -1
			};
			mAnimDataList.Add(item2);
			mAnimSequence.PlaySequence(mAnimDataList);
		}
	}

	public void ShowNpcTalk()
	{
		PartnerDetailAnimationInfo npcFriendshipLevelInfo = services.GetFriendshipAnimation(mNpcData.NpcClassId, mNpcData.FriendShipLevel);
		int num = npcFriendshipLevelInfo.TalkIdList[services.RandomRange(0, npcFriendshipLevelInfo.TalkIdList.Count)];
		string key = $"npc_talk_{num}";
		mNpcTalkUI.ShowNpcTalk(key);
	}
}

}
